'use strict';

// MODULES //

var tape = require( 'tape' );
var wrap = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof wrap, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function wraps a provided text string', function test( t ) {
	var expected;
	var actual;
	var txt;

	txt = 'Computes the squared absolute value for each element in a strided array `x` and assigns the results to elements in a strided array `y`.';

	expected = '    Computes the squared absolute value for each element in a strided array `x`\n    and assigns the results to elements in a strided array `y`.';

	actual = wrap( txt, 4 );

	t.strictEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function wraps a provided text string', function test( t ) {
	var expected;
	var actual;
	var txt;

	txt = 'Computes the absolute value of each element retrieved from a strided input array `x` via a callback function and assigns each result to an element in a strided output array `y`.';

	expected = '    Computes the absolute value of each element retrieved from a strided input\n    array `x` via a callback function and assigns each result to an element in a\n    strided output array `y`.';

	actual = wrap( txt, 4 );

	t.strictEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function wraps a provided text string', function test( t ) {
	var expected;
	var actual;
	var txt;

	txt = 'Computes the squared absolute value for each element in a strided array `x` and assigns the results to elements in a strided array `y` using alternative indexing semantics.';

	expected = '    Computes the squared absolute value for each element in a strided array `x`\n    and assigns the results to elements in a strided array `y` using alternative\n    indexing semantics.';

	actual = wrap( txt, 4 );

	t.strictEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function wraps a provided text string', function test( t ) {
	var expected;
	var actual;
	var txt;

	txt = 'Returns a function which dispatches to specified functions based on input argument types.';

	expected = '    Returns a function which dispatches to specified functions based on input\n    argument types.';

	actual = wrap( txt, 4 );

	t.strictEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function does not break before close punctuation', function test( t ) {
	var expected;
	var actual;
	var txt;

	txt = 'Computes the absolute value of a double-precision floating-point number `x`.';

	expected = '    Computes the absolute value of a double-precision floating-point number `x`.';

	actual = wrap( txt, 4 );

	t.strictEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function breaks at hyphens', function test( t ) {
	var expected;
	var actual;
	var txt;

	txt = 'however, that values between `start` and `stop` are subject to floating-point rounding errors.';

	expected = '    however, that values between `start` and `stop` are subject to floating-\n    point rounding errors.';

	actual = wrap( txt, 4 );

	t.strictEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports custom indent levels', function test( t ) {
	var expected;
	var actual;
	var txt;

	txt = 'Number of indexed elements.';

	expected = '        Number of indexed elements.';

	actual = wrap( txt, 8 );

	t.strictEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports a custom max width', function test( t ) {
	var expected;
	var actual;
	var txt;

	txt = 'This is a floating-point double-precision value.';

	expected = '    This is a floating-point\n    double-precision value.';

	actual = wrap( txt, 4, 32 );

	t.strictEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function returns text unchanged if it fits on one line', function test( t ) {
	var expected;
	var actual;
	var txt;

	txt = 'Short text.';

	expected = '    Short text.';

	actual = wrap( txt, 4 );

	t.strictEqual( actual, expected, 'returns expected value' );
	t.end();
});
